    tokens = []
    i = 0
    while i < len(p):
        atom = p[i]
        q = ""
        if i + 1 < len(p) and p[i + 1] in "*+?":
            q = p[i + 1]
            i += 2
        else:
            i += 1
        tokens.append((atom, q))

    dp = [False] * (n + 1)
    dp[0] = True

    for atom, q in tokens:
        ndp = [False] * (n + 1)

        if q == "":
            for j, ch in enumerate(s, 1):
                ndp[j] = dp[j - 1] and (atom == "." or atom == ch)

        elif q == "?":
            ndp[0] = dp[0]
            for j, ch in enumerate(s, 1):
                ndp[j] = dp[j] or (dp[j - 1] and (atom == "." or atom == ch))

        elif q == "*":
            ndp[0] = dp[0]
            for j, ch in enumerate(s, 1):
                ndp[j] = dp[j] or (ndp[j - 1] and (atom == "." or atom == ch))

        else:  # "+"
            for j, ch in enumerate(s, 1):
                m = atom == "." or atom == ch
                ndp[j] = (dp[j - 1] and m) or (ndp[j - 1] and m)

        dp = ndp

    return dp[n]
