def count_n_queens(n: int) -> int:
    if n < 0:
        return 0
    if n == 0:
        return 1

    full = (1 << n) - 1

    def dfs(cols, diag1, diag2, full=full):
        if cols == full:
            return 1

        available = full & ~(cols | diag1 | diag2)
        total = 0

        while available:
            bit = available & -available
            available ^= bit

            total += dfs(
                cols | bit,
                ((diag1 | bit) << 1) & full,
                (diag2 | bit) >> 1,
            )

        return total

    def count_from_first(col):
        bit = 1 << col
        return dfs(bit, (bit << 1) & full, bit >> 1)

    half = n // 2
    total = 0

    for col in range(half):
        total += count_from_first(col)

    total *= 2

    if n & 1:
        total += count_from_first(half)

    return total
