from __future__ import annotations

def islands_after_adds(rows: int, cols: int, positions: list[tuple[int, int]]) -> list[int]:
    parent = [-1] * (rows * cols)
    rank = [0] * (rows * cols)
    counts = []
    islands = 0

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        nonlocal islands
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1
        islands -= 1

    for r, c in positions:
        idx = r * cols + c

        if parent[idx] != -1:
            counts.append(islands)
            continue

        parent[idx] = idx
        islands += 1

        if r > 0:
            nb = idx - cols
            if parent[nb] != -1:
                union(idx, nb)

        if r + 1 < rows:
            nb = idx + cols
            if parent[nb] != -1:
                union(idx, nb)

        if c > 0:
            nb = idx - 1
            if parent[nb] != -1:
                union(idx, nb)

        if c + 1 < cols:
            nb = idx + 1
            if parent[nb] != -1:
                union(idx, nb)

        counts.append(islands)

    return counts
