from typing import List

def median_sliding_window(nums: List[int], k: int) -> List[float]:
    n = len(nums)
    if k <= 0 or k > n:
        return []

    values = sorted(set(nums))
    comp = {v: i + 1 for i, v in enumerate(values)}
    m = len(values)
    bit = [0] * (m + 1)

    def add(i, delta, bit=bit, m=m):
        while i <= m:
            bit[i] += delta
            i += i & -i

    top_bit = 1 << (m.bit_length() - 1)

    def kth(order, bit=bit, m=m, top_bit=top_bit):
        idx = 0
        step = top_bit
        while step:
            nxt = idx + step
            if nxt <= m and bit[nxt] < order:
                idx = nxt
                order -= bit[nxt]
            step >>= 1
        return idx

    for i in range(k):
        add(comp[nums[i]], 1)

    res: List[float] = []

    if k & 1:
        mid_order = k // 2 + 1
        for right in range(k - 1, n):
            res.append(float(values[kth(mid_order)]))
            if right + 1 < n:
                add(comp[nums[right - k + 1]], -1)
                add(comp[nums[right + 1]], 1)
    else:
        lo_order = k // 2
        hi_order = k // 2 + 1
        for right in range(k - 1, n):
            lo = values[kth(lo_order)]
            hi = values[kth(hi_order)]
            res.append((lo + hi) / 2.0)
            if right + 1 < n:
                add(comp[nums[right - k + 1]], -1)
                add(comp[nums[right + 1]], 1)

    return res
