from math import gcd

def max_points(points: list[tuple[int, int]]) -> int:
    if not points:
        return 0

    tally = Counter(points)
    items = list(tally.items())

    if len(items) == 1:
        return len(points)

    best = 0

    for i, ((x0, y0), base_count) in enumerate(items):
        directions = {}

        for j, ((x1, y1), count) in enumerate(items):
            if i == j:
                continue

            dx = x1 - x0
            dy = y1 - y0
            g = gcd(abs(dx), abs(dy))

            dx //= g
            dy //= g

            if dx < 0 or (dx == 0 and dy < 0):
                dx = -dx
                dy = -dy

            key = (dx, dy)
            directions[key] = directions.get(key, 0) + count

        best = max(best, base_count + max(directions.values()))

    return best
