class Parser:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.n = len(text)

    def parse(self):
        self.skip_ws()
        value = self.parse_value()
        self.skip_ws()
        if self.pos != self.n:
            raise ValueError("trailing characters")
        return value

    def skip_ws(self):
        while self.pos < self.n and self.text[self.pos] in ' \t\n\r':
            self.pos += 1

    def parse_value(self):
        if self.pos >= self.n:
            raise ValueError("unexpected end")
        c = self.text[self.pos]
        if c == '{':
            return self.parse_object()
        if c == '[':
            return self.parse_array()
        if c == '"':
            return self.parse_string()
        if c == 't':
            return self.parse_true()
        if c == 'f':
            return self.parse_false()
        if c == 'n':
            return self.parse_null()
        if c == '-' or ('0' <= c <= '9'):
            return self.parse_number()
        raise ValueError(f"unexpected character {c!r}")

    def parse_true(self):
        if self.text.startswith('true', self.pos):
            self.pos += 4
            return True
        raise ValueError("invalid literal")

    def parse_false(self):
        if self.text.startswith('false', self.pos):
            self.pos += 5
            return False
        raise ValueError("invalid literal")

    def parse_null(self):
        if self.text.startswith('null', self.pos):
            self.pos += 4
            return None
        raise ValueError("invalid literal")

    def parse_number(self):
        start = self.pos

        if self.text[self.pos] == '-':
            self.pos += 1
            if self.pos >= self.n or not ('0' <= self.text[self.pos] <= '9'):
                raise ValueError("invalid number")

        c = self.text[self.pos]
        if c == '0':
            self.pos += 1
            if self.pos < self.n and '0' <= self.text[self.pos] <= '9':
                raise ValueError("leading zeros are not allowed")
        else:
            if not ('1' <= c <= '9'):
                raise ValueError("invalid number")
            while self.pos < self.n and '0' <= self.text[self.pos] <= '9':
                self.pos += 1

        has_frac = False
        if self.pos < self.n and self.text[self.pos] == '.':
            has_frac = True
            self.pos += 1
            if self.pos >= self.n or not ('0' <= self.text[self.pos] <= '9'):
                raise ValueError("invalid number")
            while self.pos < self.n and '0' <= self.text[self.pos] <= '9':
                self.pos += 1

        has_exp = False
        if self.pos < self.n and self.text[self.pos] in 'eE':
            has_exp = True
            self.pos += 1
            if self.pos < self.n and self.text[self.pos] in '+-':
                self.pos += 1
            if self.pos >= self.n or not ('0' <= self.text[self.pos] <= '9'):
                raise ValueError("invalid number")
            while self.pos < self.n and '0' <= self.text[self.pos] <= '9':
                self.pos += 1

        substr = self.text[start:self.pos]
        if has_frac or has_exp:
            return float(substr)
        return int(substr)

    def parse_string(self):
        if self.text[self.pos] != '"':
            raise ValueError("expected string")
        self.pos += 1
        result = []

        while True:
            if self.pos >= self.n:
                raise ValueError("unterminated string")

            ch = self.text[self.pos]

            if ch == '"':
                self.pos += 1
                return ''.join(result)

            if ch == '\\':
                self.pos += 1
                if self.pos >= self.n:
                    raise ValueError("unterminated string")
                esc = self.text[self.pos]
                self.pos += 1

                if esc == '"':
                    result.append('"')
                elif esc == '\\':
                    result.append('\\')
                elif esc == '/':
                    result.append('/')
                elif esc == 'b':
                    result.append('\b')
                elif esc == 'f':
                    result.append('\f')
                elif esc == 'n':
                    result.append('\n')
                elif esc == 'r':
                    result.append('\r')
                elif esc == 't':
                    result.append('\t')
                elif esc == 'u':
                    if self.pos + 4 > self.n:
                        raise ValueError("invalid unicode escape")
                    hex_digits = self.text[self.pos:self.pos + 4]
                    if not all(c in '0123456789abcdefABCDEF' for c in hex_digits):
                        raise ValueError("invalid unicode escape")
                    result.append(chr(int(hex_digits, 16)))
                    self.pos += 4
                else:
                    raise ValueError("invalid escape")
            else:
                if ord(ch) < 0x20:
                    raise ValueError("unescaped control character in string")
                result.append(ch)
                self.pos += 1

    def parse_object(self):
        self.pos += 1
        obj = {}
        self.skip_ws()

        if self.pos < self.n and self.text[self.pos] == '}':
            self.pos += 1
            return obj

        while True:
            self.skip_ws()
            if self.pos >= self.n:
                raise ValueError("unterminated object")
            if self.text[self.pos] != '"':
                raise ValueError("expected string key")

            key = self.parse_string()
            self.skip_ws()

            if self.pos >= self.n or self.text[self.pos] != ':':
                raise ValueError("expected colon")
            self.pos += 1
            self.skip_ws()

            obj[key] = self.parse_value()
            self.skip_ws()

            if self.pos >= self.n:
                raise ValueError("unterminated object")

            ch = self.text[self.pos]
            if ch == ',':
                self.pos += 1
                self.skip_ws()
                if self.pos < self.n and self.text[self.pos] == '}':
                    raise ValueError("trailing comma")
            elif ch == '}':
                self.pos += 1
                return obj
            else:
                raise ValueError("expected ',' or '}'")

    def parse_array(self):
        self.pos += 1
        arr = []
        self.skip_ws()

        if self.pos < self.n and self.text[self.pos] == ']':
            self.pos += 1
            return arr

        while True:
            self.skip_ws()
            if self.pos >= self.n:
                raise ValueError("unterminated array")

            arr.append(self.parse_value())
            self.skip_ws()

            if self.pos >= self.n:
                raise ValueError("unterminated array")

            ch = self.text[self.pos]
            if ch == ',':
                self.pos += 1
                self.skip_ws()
                if self.pos < self.n and self.text[self.pos] == ']':
                    raise ValueError("trailing comma")
            elif ch == ']':
                self.pos += 1
                return arr
            else:
                raise ValueError("expected ',' or ']'")


