            if word == 'true':
                tokens.append(('LITERAL', True))
            elif word == 'false':
                tokens.append(('LITERAL', False))
            elif word in ('not', 'and', 'or'):
                tokens.append(('OP', word))
            else:
                tokens.append(('IDENT', word))
        else:
            raise ValueError(f"Unexpected character: {c}")

    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return None

    def consume():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        return parse_or()

    def parse_or():
        left = parse_and()
        while True:
            tok = peek()
            if tok and tok[0] == 'OP' and tok[1] == 'or':
                consume()
                right = parse_and()
                left = left or right
            else:
                return left

    def parse_and():
        left = parse_not()
        while True:
            tok = peek()
            if tok and tok[0] == 'OP' and tok[1] == 'and':
                consume()
                right = parse_not()
                left = left and right
            else:
                return left

    def parse_not():
        tok = peek()
        if tok and tok[0] == 'OP' and tok[1] == 'not':
            consume()
            return not parse_not()
        return parse_primary()

    def parse_primary():
        tok = peek()
        if tok is None:
            raise SyntaxError("Unexpected end of expression")
        if tok[0] == 'LITERAL':
            consume()
            return tok[1]
        if tok[0] == 'IDENT':
            consume()
            name = tok[1]
            if name not in env:
                raise KeyError(name)
            return env[name]
        if tok[0] == 'LPAREN':
            consume()
            val = parse_expr()
            tok = peek()
            if tok is None or tok[0] != 'RPAREN':
                raise SyntaxError("Expected ')'")
            consume()
            return val
        raise SyntaxError(f"Unexpected token: {tok}")

    result = parse_expr()
    if pos != len(tokens):
        raise SyntaxError("Unexpected tokens after expression")
    return result
