from typing import List, Tuple

def islands_after_adds(rows: int, cols: int, positions: List[Tuple[int, int]]) -> List[int]:
    total = rows * cols
    parent = [-1] * total
    size = [0] * total

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> bool:
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return False

        if size[ra] < size[rb]:
            ra, rb = rb, ra

        parent[rb] = ra
        size[ra] += size[rb]
        return True

    islands = 0
    ans = []
    append = ans.append

    for r, c in positions:
        if not (0 <= r < rows and 0 <= c < cols):
            append(islands)
            continue

        idx = r * cols + c

        if parent[idx] != -1:
            append(islands)
            continue

        parent[idx] = idx
        size[idx] = 1
        islands += 1

        if r > 0:
            nb = idx - cols
            if parent[nb] != -1 and union(idx, nb):
                islands -= 1

        if r + 1 < rows:
            nb = idx + cols
            if parent[nb] != -1 and union(idx, nb):
                islands -= 1

        if c > 0:
            nb = idx - 1
            if parent[nb] != -1 and union(idx, nb):
                islands -= 1

        if c + 1 < cols:
            nb = idx + 1
            if parent[nb] != -1 and union(idx, nb):
                islands -= 1

        append(islands)

    return ans
